insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (7034, 16, 'Zuschüsse für neue klimafreundliche Heizungen fortführen oder ausbauen', 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'gemischt', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'bund', null, true, null),
  (7035, 16, 'Wärmepumpen-Leasing oder Wärme-Contracting ohne hohe Startinvestition', 'Nimmt Haushalten die hohe Anfangsinvestition ab, die laut KfW oft fehlt; solche Angebote gibt es bisher nur vereinzelt, ihre Wirkung in der Breite ist kaum untersucht.', 'offen', null, 'bund', null, true, null),
  (7036, 16, 'Heizungsgesetz abschaffen, freie Wahl der Heizung', 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'gemischt', null, 'bund', null, true, null),
  (7037, 16, 'Geltende Vorgaben beibehalten, Planungssicherheit bis 2045', 'Vermeidet weitere Wechsel der Regeln; die Vorgaben selbst waren stark umstritten, und ob sie Regierungswechsel überdauern, ist offen – 2026 wurden sie grundlegend geändert.', 'gemischt', null, 'bund', null, true, null),
  (7038, 16, 'Kommunale Wärmeplanung und Wärmenetze fördern', 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'gemischt', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'bund', null, true, null),
  (7039, 16, 'Modernisierungsumlage für energetische Sanierung abschaffen, Warmmietenneutralität', 'Schützt Mieterinnen und Mieter vor Mietsteigerungen durch den Heizungstausch; zugleich sinkt der Anreiz für Vermieter, die Heizung zu erneuern, sodass Mieter länger die Kosten alter Heizungen tragen können.', 'gemischt', null, 'bund', null, true, null),
  (7158, 16, 'Kommunale Wärmeplanung und Wärmenetze unterstützen: Beratung, Personal, Förderung (Landesprogramm)', 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'gemischt', null, 'land', null, true, null),
  (7159, 16, 'Kommunale Wärmeplanung vereinfachen, realistische Vorgaben (Landesprogramm)', 'Kann die Planung für kleine Gemeinden beschleunigen; wenn Pläne gröber werden, wissen Eigentümer aber weniger genau, was kommt.', 'offen', null, 'land', null, true, null),
  (7160, 16, 'Pflicht zur kommunalen Wärmeplanung abschaffen (Landesprogramm)', 'Nimmt Kommunen eine Pflicht ab und Eigentümern das Warten auf einen Plan, schafft aber keine Klarheit, ob ein Wärmenetz kommt. Die Pflicht steht im Bundesrecht; das Land kann nur sein Ausführungsgesetz ändern oder im Bundesrat werben.', 'offen', null, 'land', null, true, null)
